<?php $adjust=$type==='ADJUSTMENT';echo form_open(get_uri('warehouses/movements/save'),['id'=>'warehouse-movement-form']);echo csrf_field(); ?><div class="modal-header"><h5 class="modal-title"><?php echo['ENTRY'=>'Nueva entrada','EXIT'=>'Nueva salida','ADJUSTMENT'=>'Nuevo ajuste'][$type]; ?></h5><button class="btn-close" data-bs-dismiss="modal"></button></div><div class="modal-body"><input type="hidden" name="movement_type" value="<?php echo$type; ?>"><div class="row"><div class="col-md-6"><label>Almacén</label><?php echo form_dropdown('warehouse_id',$warehouses,'',"class='form-control select2' required"); ?></div><div class="col-md-6"><label>Fecha</label><input type="datetime-local" class="form-control" name="movement_date" value="<?php echo date('Y-m-d\TH:i'); ?>" required></div></div><div class="row"><div class="col-md-4"><label>Tipo referencia</label><?php echo form_dropdown('reference_type',[''=>'-','FACTURA'=>'Factura','REMISION'=>'Remisión','EVENTO'=>'Evento','PROYECTO'=>'Proyecto','EXTERNO'=>'Externo','OTRO'=>'Otro'],'',"class='form-control'"); ?></div><div class="col-md-8"><label>Referencia</label><input class="form-control" name="reference_text"></div></div><label>Observaciones</label><textarea class="form-control" name="notes"></textarea><hr><h6>Productos</h6><table class="table" id="movement-lines"><thead><tr><th>Producto de almacén</th><th><?php echo$adjust?'Existencia física':'Cantidad'; ?></th><th>Notas</th><th></th></tr></thead><tbody><tr data-line><td><?php echo form_dropdown('lines[0][warehouse_product_id]',$products,'',"class='form-control select2' required"); ?></td><td><input class="form-control" inputmode="decimal" name="lines[0][<?php echo$adjust?'physical_quantity':'quantity'; ?>]" required></td><td><input class="form-control" name="lines[0][notes]"></td><td><button type="button" class="btn btn-default remove-line">×</button></td></tr></tbody></table><button type="button" id="add-movement-line" class="btn btn-default">+ Agregar producto</button><?php if($adjust): ?><div class="alert alert-info mt10">Al confirmar se calculará la diferencia contra la existencia vigente y se registrará como delta trazable.</div><?php endif; ?></div><div class="modal-footer"><button class="btn btn-default" type="button" data-bs-dismiss="modal">Cancelar</button><button class="btn btn-primary">Guardar borrador</button></div><?php echo form_close(); ?><script>$(function(){var i=1,body=$('#movement-lines tbody'),template=body.find('tr').first().clone();$('#add-movement-line').click(function(){var r=template.clone();r.find('select,input').each(function(){this.name=this.name.replace('[0]','['+i+']');$(this).val('');});body.append(r);r.find('.select2').select2();i++;});body.on('click','.remove-line',function(){if(body.find('tr').length>1)$(this).closest('tr').remove();});$('#warehouse-movement-form').appForm({closeModalOnSuccess:false,onSuccess:function(r){window.location.href=r.redirect;}});});</script>
